const cs = Array.from(readFileSync(0, 'utf8'))
const KEYWORDS = new Set(['let', 'if', 'else', 'while', 'return', 'true', 'false', 'null'])
const PUNCT = ['==', '!=', '<=', '>=', '&&', '||', '->', '=>', '+', '-', '*', '/', '%', '=', '<', '>', '!', '(', ')', '{', '}', '[', ']', ',', ';', '.']
const isDigit = (c) => c !== undefined && c >= '0' && c <= '9'
const isLetter = (c) => c !== undefined && ((c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z'))
const isIdStart = (c) => isLetter(c) || c === '_'
const isIdChar = (c) => isIdStart(c) || isDigit(c)
const isHex = (c) => c !== undefined && /^[0-9a-fA-F]$/.test(c)

class ScanError extends Error {
  constructor(pos, reason) {
    super(reason)
    this.pos = pos
  }
}

const tokens = []
let i = 0
let line = 1
let col = 1
const n = cs.length

function advance() {
  const c = cs[i++]
  if (c === '\n') { line++; col = 1 }
  else if (c === '\t') col = Math.floor((col - 1) / 4) * 4 + 5
  else col++
  return c
}
function advanceN(k) { for (let j = 0; j < k; j++) advance() }

function digitRun(j, test) {
  // consumes digits with single underscores between digits; returns end index
  while (j < n) {
    if (test(cs[j])) j++
    else if (cs[j] === '_' && j > 0 && test(cs[j - 1]) && test(cs[j + 1])) j++
    else break
  }
  return j
}

function scanNumber() {
  const start = i
  let j = i
  let ok = true
  const c1 = cs[j + 1]
  let test = isDigit
  let prefixed = false
  if (cs[j] === '0' && c1 !== undefined && 'xXbBoO'.includes(c1)) {
    prefixed = true
    const p = c1.toLowerCase()
    test = p === 'x' ? isHex : p === 'b' ? (c) => c === '0' || c === '1' : (c) => c !== undefined && c >= '0' && c <= '7'
    j += 2
    if (!test(cs[j])) ok = false
    else j = digitRun(j, test)
  } else {
    j = digitRun(j, isDigit)
    if (cs[j] === '.' && isDigit(cs[j + 1])) j = digitRun(j + 1, isDigit)
    if (cs[j] === 'e' || cs[j] === 'E') {
      let k = j + 1
      if (cs[k] === '+' || cs[k] === '-') k++
      if (isDigit(cs[k])) j = digitRun(k, isDigit)
    }
  }
  if (!ok || isIdChar(cs[j])) {
    while (isIdChar(cs[j])) j++
    throw new ScanError([line, col], 'invalid number ' + cs.slice(start, j).join(''))
  }
  tokens.push([line, col, 'number', cs.slice(start, j).join('')])
  advanceN(j - start)
}

function scanString() {
  const pos = [line, col]
  const unterminated = new ScanError(pos, 'unterminated string')
  advance()
  let out = ''
  for (;;) {
    if (i >= n) throw unterminated
    const c = cs[i]
    if (c === '"') { advance(); break }
    if (c === '\n') throw new ScanError([line, col], 'newline in string')
    if (c !== '\\') { out += c; advance(); continue }
    const bpos = [line, col]
    if (i + 1 >= n) throw unterminated
    const e = cs[i + 1]
    const bad = () => new ScanError(bpos, 'invalid escape \\' + e)
    const simple = { n: '\n', t: '\t', r: '\r', '\\': '\\', '"': '"', 0: '\0' }
    if (Object.hasOwn(simple, e)) { out += simple[e]; advanceN(2); continue }
    if (e === 'x') {
      if (!isHex(cs[i + 2]) || !isHex(cs[i + 3])) throw bad()
      out += String.fromCharCode(parseInt(cs[i + 2] + cs[i + 3], 16))
      advanceN(4)
      continue
    }
    if (e === 'u') {
      if (cs[i + 2] !== '{') throw bad()
      let j = i + 3
      let h = ''
      while (isHex(cs[j])) h += cs[j++]
      if (h === '' || cs[j] !== '}') throw bad()
      const v = parseInt(h, 16)
      if (v > 0x10ffff) throw bad()
      out += String.fromCodePoint(v)
      advanceN(j + 1 - i)
      continue
    }
    throw bad()
  }
  tokens.push([pos[0], pos[1], 'string', JSON.stringify(out)])
}

function scan() {
  while (i < n) {
    const c = cs[i]
    if (c === ' ' || c === '\t' || c === '\r' || c === '\n') { advance(); continue }
    if (c === '/' && cs[i + 1] === '/') {
      while (i < n && cs[i] !== '\n') advance()
      continue
    }
    if (c === '/' && cs[i + 1] === '*') {
      const pos = [line, col]
      let depth = 0
      do {
        if (i >= n) throw new ScanError(pos, 'unterminated block comment')
        if (cs[i] === '/' && cs[i + 1] === '*') { depth++; advanceN(2) }
        else if (cs[i] === '*' && cs[i + 1] === '/') { depth--; advanceN(2) }
        else advance()
      } while (depth > 0)
      continue
    }
    if (c === 'r' && cs[i + 1] === '"') {
      const pos = [line, col]
      let j = i + 2
      while (j < n && cs[j] !== '"') j++
      if (j >= n) throw new ScanError(pos, 'unterminated string')
      const body = cs.slice(i + 2, j).join('')
      tokens.push([pos[0], pos[1], 'rawstring', JSON.stringify(body)])
      advanceN(j + 1 - i)
      continue
    }
