    if (c === '"') { scanString(); continue }
    const two = c + (cs[i + 1] ?? '')
    const p = PUNCT.find((x) => (x.length === 2 ? x === two : x === c))
    if (p) {
      tokens.push([line, col, 'punct', p])
      advanceN(p.length)
      continue
    }
    throw new ScanError([line, col], 'unexpected character ' + c)
  }
